import Mathlib

/-- The set of values in the array. -/
def ArrayValues (s : Array Int) : Finset Int :=
  Finset.image (fun (i : Fin s.size) => s[i.1]!) Finset.univ

/-- The second smallest element of a finite set of integers. -/
def secondSmallestFinset (fs : Finset Int) (h : fs.Nonempty) (h2 : (fs.image (· / 2)).card < fs.card) : Int :=
  let sorted := fs.insertSorted.toList.sort (· ≤ ·)
  sorted.getD 1 0

/-- A more direct way to define the second smallest value in a non-empty set. -/
def secondSmallestVal (fs : Finset Int) : Int :=
  let sorted := fs.toList.sort (· ≤ ·)
  sorted.getD 1 0

/-- `secondSmallestVal` is the `getD 1 0` of the sorted list of values. -/
lemma secondSmallestVal_def (fs : Finset Int) :
    secondSmallestVal fs = (fs.toList.sort (· ≤ ·)).getD 1 0 := rfl

/-- The value `v` is the `k`-th smallest element of the array. -/
def is_kth_smallest (s : Array Int) (v : Int) (k : Nat) : Prop :=
  ∃ (l : List Int), l.Sorted (· ≤ ·) ∧ l.Nodup ∧ l.length = s.size ∧ (∀ x ∈ l, x ∈ ArrayValues s) ∧
  (∃ i : Fin l.length, l.get i = v ∧ i.1 = k - 1)

