import Mathlib

open Std

/-- Helper: count occurrences of `x` in `xs` -/
def countOccurrences (x : Int) (xs : List Int) : Nat :=
  xs.countP (fun y => y = x)

/-- Helper: find the first element that maximizes the count, and among ties, appears first. -/
def mostFrequentCore (xs : List Int) : Int :=
  let counts := xs.map (fun x => (x, countOccurrences x xs))
  let maxCount := (counts.map (fun (_, c) => c)).maximum?.getD 0
  -- Filter the original list for elements with maxCount, then take the first.
  let filtered := xs.filter (fun x => countOccurrences x xs = maxCount)
  filtered.headD 0

