/-- Helper: find the smallest `j > i` such that `nums[i] + nums[j] = target`. -/
def findJ (nums : Array Int) (target : Int) (i : Nat) : Nat × Nat :=
  let rec go (j : Nat) : Nat × Nat :=
    if h : j < nums.size then
      if nums[i]! + nums[j]! = target then (i, j)
      else go (j + 1)
    else (0, 0)
  go (i + 1)

/-- Helper: find the smallest `i` such that there exists a valid `j > i`. -/
def findI (nums : Array Int) (target : Int) : Nat × Nat :=
  let rec go (i : Nat) : Nat × Nat :=
    if h : i < nums.size then
      let (i', j) := findJ nums target i
      if j < nums.size then (i', j) else go (i + 1)
    else (0, 0)
  go 0

